import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import advertService from '../../services/advertService';
import styles from './AdvertDetailsPage.module.css';

const AdvertDetailsPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { user, isAuthenticated } = useAuth();
    const [advert, setAdvert] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [isParticipating, setIsParticipating] = useState(false);

    useEffect(() => { loadAdvert(); }, [id]);

    const loadAdvert = async () => {
        try {
            const response = await advertService.getAdvertById(id);
            setAdvert(response.advert);
            if (user && response.advert.participatingUserIds) {
                setIsParticipating(response.advert.participatingUserIds.split(',').includes(user.id.toString()));
            }
        } catch (err) { setError('Объявление не найдено'); }
        finally { setLoading(false); }
    };

    const handleSubscribe = async () => {
        if (!isAuthenticated) { navigate('/login'); return; }
        try {
            if (isParticipating) await advertService.unsubscribeFromAdvert(id);
            else await advertService.subscribeToAdvert(id);
            await loadAdvert();
        } catch (err) { alert(err.message); }
    };

    const handleDelete = async () => {
        if (window.confirm('Удалить объявление?')) {
            try { await advertService.deleteAdvert(id); navigate('/'); }
            catch (err) { alert(err.message); }
        }
    };

    if (loading) return <div className={styles.loading}>Загрузка...</div>;
    if (error) return <div className={styles.error}>{error}</div>;
    if (!advert) return null;

    const isCreator = user && advert.userId === user.id;
    const isFull = advert.participantsCount >= advert.peopleCount;

    return (
        <div className={styles.detailsPage}>
            <div className={styles.container}>
                <button className={styles.backButton} onClick={() => navigate(-1)}>← Назад</button>
                <div className={styles.card}>
                    <div className={styles.header}>
                        <div className={styles.levelBadge}>Уровень {advert.gameLevel === 'D4Plus' ? 'D4+' : advert.gameLevel}</div>
                        {isCreator && <div className={styles.creatorBadge}>Ваше объявление</div>}
                    </div>
                    <div className={styles.content}>
                        <div className={styles.section}><h3>📍 Место проведения</h3><p>{advert.address}</p></div>
                        <div className={styles.infoGrid}>
                            <div className={styles.section}><h3>📅 Дата</h3><p>{new Date(advert.date).toLocaleDateString('ru-RU')}</p></div>
                            <div className={styles.section}><h3>⏰ Время</h3><p>{advert.startTime?.slice(0,5)} - {advert.endTime?.slice(0,5)}</p></div>
                            <div className={styles.section}><h3>👥 Участники</h3><p>{advert.participantsCount} / {advert.peopleCount}</p></div>
                            <div className={styles.section}><h3>💰 Стоимость</h3><p>{advert.cost} BYN</p></div>
                        </div>
                        {advert.description && <div className={styles.section}><h3>📝 Описание</h3><p>{advert.description}</p></div>}
                    </div>
                    <div className={styles.footer}>
                        {isCreator ? (
                            <div className={styles.creatorActions}>
                                <Button variant="outline" onClick={() => navigate(`/add-advert?edit=${advert.id}`)}>Редактировать</Button>
                                <Button variant="danger" onClick={handleDelete}>Удалить</Button>
                            </div>
                        ) : (
                            <Button fullWidth variant={isParticipating ? 'secondary' : 'primary'} onClick={handleSubscribe} disabled={!isParticipating && isFull}>
                                {isParticipating ? 'Отменить запись' : (isFull ? 'Мест нет' : 'Записаться')}
                            </Button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AdvertDetailsPage;
